{
  "name": "opencode-one-client",
  "version": "0.2.0",
  "description": "Multi-device OpenCode companion — switch between your OpenCode servers with /remote, /device, /open slash commands and the ocd CLI（OpenCode 多设备伴侣）",
  "type": "module",
  "main": "./src/index.ts",
  "exports": {
    ".": "./src/index.ts",
    "./tui": "./src/tui.ts",
    "./package.json": "./package.json"
  },
  "bin": {
    "ocd": "./bin/ocd.js"
  },
  "files": [
    "src",
    "bin",
    "opencode-one-client.example.json",
    "README.md",
    "LICENSE"
  ],
  "keywords": [
    "opencode",
    "opencode-plugin",
    "devices",
    "remote",
    "tailscale",
    "tui",
    "cli"
  ],
  "license": "MIT",
  "author": "fanrj3",
  "engines": {
    "opencode": "^2.0.0",
    "node": ">=18"
  },
  "repository": {
    "type": "git",
    "url": "https://github.com/fanjr3/opencode-one-client.git"
  },
  "homepage": "https://github.com/fanjr3/opencode-one-client",
  "devDependencies": {
    "@opencode/plugin": "^2.0.26"
  }
}
